import { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import axiosInstance from '../axiosConfig';

// REQ-1.3: Tournament Display
// REQ-3.2: Join Tournament — Participant can join if open and before deadline.
const TournamentDetail = () => {
  const { id } = useParams();
  const { user } = useAuth();
  const [tournament, setTournament] = useState(null);
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    setLoading(true);
    try {
      const response = await axiosInstance.get(`/api/tournaments/${id}`);
      setTournament(response.data);
    } catch (error) {
      alert('Failed to load tournament.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const handleJoin = async () => {
    try {
      await axiosInstance.post(
        `/api/tournaments/${id}/join`,
        {},
        { headers: { Authorization: `Bearer ${user.token}` } }
      );
      fetchData();
    } catch (error) {
      alert(error.response?.data?.message || 'Failed to join tournament.');
    }
  };

  if (loading) return <div className="text-center mt-20">Loading...</div>;
  if (!tournament) return <div className="text-center mt-20">Tournament not found.</div>;

  const alreadyJoined =
    user && tournament.participants.some((p) => p._id === user.id);

  return (
    <div className="container mx-auto p-6">
      <h1 className="text-3xl font-bold">{tournament.name}</h1>
      <p className="text-gray-600 mb-2">{tournament.sport}</p>
      <p className="mb-4">{tournament.description}</p>
      <p className="text-sm text-gray-500">
        Date: {new Date(tournament.date).toLocaleDateString()}
      </p>
      <p className="text-sm text-gray-500 mb-4">
        Capacity: {tournament.participants.length}/{tournament.maxCapacity} &middot; Status: {tournament.status}
      </p>

      {user && user.role === 'Participant' && (
        <button
          onClick={handleJoin}
          disabled={alreadyJoined || tournament.status !== 'Open'}
          className="bg-green-600 text-white px-4 py-2 rounded disabled:bg-gray-400"
        >
          {alreadyJoined ? 'Already Joined' : 'Join Tournament'}
        </button>
      )}
      {!user && <p className="text-sm text-gray-500">Log in as a Participant to join.</p>}
    </div>
  );
};

export default TournamentDetail;
